        for c in range(w - 1):
            if all(grid[y][x] == 2 for y in (r, r + 1) for x in (c, c + 1)):
                # Only use the top-left cell of a maximal block.
                if c == 0 or grid[r][c - 1] != 2:
                    if r == 0 or grid[r - 1][c] != 2:
                        blocks.append((r, c))
    out = [row[:] for row in grid]
    if not blocks:
        return out
